 62→// InstallHooks installs Claude Code hooks in .claude/settings.json.
 63→// If force is true, removes existing Entire hooks before installing.
 64→// Returns the number of hooks installed.
 65→func (c *ClaudeCodeAgent) InstallHooks(localDev bool, force bool) (int, error) {
 66→	// Use repo root instead of CWD to find .claude directory
 67→	// This ensures hooks are installed correctly when run from a subdirectory
 68→	repoRoot, err := paths.RepoRoot()
 69→	if err != nil {
 70→		// Fallback to CWD if not in a git repo (e.g., during tests)
 71→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
 72→		if err != nil {
 73→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 74→		}
 75→	}
 76→
 77→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
 78→
 79→	// Read existing settings if they exist
 80→	var rawSettings map[string]json.RawMessage
 81→
 82→	// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
 83→	var rawHooks map[string]json.RawMessage
 84→
 85→	// rawPermissions preserves unknown permission fields (e.g., "ask")
 86→	var rawPermissions map[string]json.RawMessage
 87→
 88→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from cwd + fixed path
 89→	if readErr == nil {
 90→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
 91→			return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
 92→		}
 93→		if hooksRaw, ok := rawSettings["hooks"]; ok {
 94→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 95→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
 96→			}
 97→		}
 98→		if permRaw, ok := rawSettings["permissions"]; ok {
 99→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
100→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
101→			}
102→		}
103→	} else {
104→		rawSettings = make(map[string]json.RawMessage)
105→	}
106→
107→	if rawHooks == nil {
108→		rawHooks = make(map[string]json.RawMessage)
109→	}
110→	if rawPermissions == nil {
111→		rawPermissions = make(map[string]json.RawMessage)
112→	}
113→
114→	// Parse only the hook types we need to modify
115→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
116→	parseHookType(rawHooks, "SessionStart", &sessionStart)
117→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
118→	parseHookType(rawHooks, "Stop", &stop)
119→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
120→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
121→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
122→
123→	// If force is true, remove all existing Entire hooks first
124→	if force {
125→		sessionStart = removeEntireHooks(sessionStart)
126→		sessionEnd = removeEntireHooks(sessionEnd)
127→		stop = removeEntireHooks(stop)
128→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
129→		preToolUse = removeEntireHooksFromMatchers(preToolUse)
130→		postToolUse = removeEntireHooksFromMatchers(postToolUse)
131→	}
132→
133→	// Define hook commands
134→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd, postFileEditCmd string
135→	if localDev {
136→		sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-start"
137→		sessionEndCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-end"
138→		stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
139→		userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code user-prompt-submit"
140→		preTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code pre-task"
141→		postTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
142→		postTodoCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-todo"
143→		postFileEditCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-file-edit"
144→	} else {
145→		sessionStartCmd = "entire hooks claude-code session-start"
146→		sessionEndCmd = "entire hooks claude-code session-end"
147→		stopCmd = "entire hooks claude-code stop"
148→		userPromptSubmitCmd = "entire hooks claude-code user-prompt-submit"
149→		preTaskCmd = "entire hooks claude-code pre-task"
150→		postTaskCmd = "entire hooks claude-code post-task"
151→		postTodoCmd = "entire hooks claude-code post-todo"
152→		postFileEditCmd = "entire hooks claude-code post-file-edit"
153→	}
154→
155→	count := 0
156→
157→	// Add hooks if they don't exist
158→	if !hookCommandExists(sessionStart, sessionStartCmd) {
159→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
160→		count++
161→	}
162→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
163→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
164→		count++
165→	}
166→	if !hookCommandExists(stop, stopCmd) {
167→		stop = addHookToMatcher(stop, "", stopCmd)
168→		count++
169→	}
170→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
171→		userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
172→		count++
173→	}
174→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
175→		preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
176→		count++
177→	}
178→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
179→		postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
180→		count++
181→	}
182→	if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
183→		postToolUse = addHookToMatcher(postToolUse, "TodoWrite", postTodoCmd)
184→		count++
185→	}
186→	if !hookCommandExistsWithMatcher(postToolUse, "Write", postFileEditCmd) {
187→		postToolUse = addHookToMatcher(postToolUse, "Write", postFileEditCmd)
188→		count++
189→	}
190→	if !hookCommandExistsWithMatcher(postToolUse, "Edit", postFileEditCmd) {
191→		postToolUse = addHookToMatcher(postToolUse, "Edit", postFileEditCmd)
192→		count++
193→	}
194→
195→	// Add permissions.deny rule if not present
196→	permissionsChanged := false
197→	var denyRules []string
198→	if denyRaw, ok := rawPermissions["deny"]; ok {
199→		if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
200→			return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
201→		}
202→	}
203→	if !slices.Contains(denyRules, metadataDenyRule) {
204→		denyRules = append(denyRules, metadataDenyRule)
205→		denyJSON, err := json.Marshal(denyRules)
206→		if err != nil {
207→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
208→		}
209→		rawPermissions["deny"] = denyJSON
210→		permissionsChanged = true
211→	}
212→
213→	if count == 0 && !permissionsChanged {
214→		return 0, nil // All hooks and permissions already installed
215→	}
216→
217→	// Marshal modified hook types back to rawHooks
218→	marshalHookType(rawHooks, "SessionStart", sessionStart)
219→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
220→	marshalHookType(rawHooks, "Stop", stop)
221→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
222→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
223→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
224→
225→	// Marshal hooks and update raw settings
226→	hooksJSON, err := json.Marshal(rawHooks)
227→	if err != nil {
228→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
229→	}
230→	rawSettings["hooks"] = hooksJSON
231→
232→	// Marshal permissions and update raw settings
233→	permJSON, err := json.Marshal(rawPermissions)
234→	if err != nil {
235→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
236→	}
237→	rawSettings["permissions"] = permJSON
238→
239→	// Write back to file
240→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
241→		return 0, fmt.Errorf("failed to create .claude directory: %w", err)
242→	}
243→
244→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
245→	if err != nil {
246→		return 0, fmt.Errorf("failed to marshal settings: %w", err)
247→	}
248→
249→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
250→		return 0, fmt.Errorf("failed to write settings.json: %w", err)
251→	}
252→
253→	return count, nil
254→}
