279→// UninstallHooks removes Entire hooks from Claude Code settings.
280→func (c *ClaudeCodeAgent) UninstallHooks() error {
281→	// Use repo root to find .claude directory when run from a subdirectory
282→	repoRoot, err := paths.RepoRoot()
283→	if err != nil {
284→		repoRoot = "." // Fallback to CWD if not in a git repo
285→	}
286→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
287→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
288→	if err != nil {
289→		return nil //nolint:nilerr // No settings file means nothing to uninstall
290→	}
291→
292→	var rawSettings map[string]json.RawMessage
293→	if err := json.Unmarshal(data, &rawSettings); err != nil {
294→		return fmt.Errorf("failed to parse settings.json: %w", err)
295→	}
296→
297→	// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
298→	var rawHooks map[string]json.RawMessage
299→	if hooksRaw, ok := rawSettings["hooks"]; ok {
300→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
301→			return fmt.Errorf("failed to parse hooks: %w", err)
302→		}
303→	}
304→	if rawHooks == nil {
305→		rawHooks = make(map[string]json.RawMessage)
306→	}
307→
308→	// Parse only the hook types we need to modify
309→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
310→	parseHookType(rawHooks, "SessionStart", &sessionStart)
311→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
312→	parseHookType(rawHooks, "Stop", &stop)
313→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
314→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
315→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
316→
317→	// Remove Entire hooks from all hook types
318→	sessionStart = removeEntireHooks(sessionStart)
319→	sessionEnd = removeEntireHooks(sessionEnd)
320→	stop = removeEntireHooks(stop)
321→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
322→	preToolUse = removeEntireHooksFromMatchers(preToolUse)
323→	postToolUse = removeEntireHooksFromMatchers(postToolUse)
324→
325→	// Marshal modified hook types back to rawHooks
326→	marshalHookType(rawHooks, "SessionStart", sessionStart)
327→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
328→	marshalHookType(rawHooks, "Stop", stop)
329→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
330→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
331→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
332→
333→	// Also remove the metadata deny rule from permissions
334→	var rawPermissions map[string]json.RawMessage
335→	if permRaw, ok := rawSettings["permissions"]; ok {
336→		if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
337→			// If parsing fails, just skip permissions cleanup
338→			rawPermissions = nil
339→		}
340→	}
341→
342→	if rawPermissions != nil {
343→		if denyRaw, ok := rawPermissions["deny"]; ok {
344→			var denyRules []string
345→			if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
346→				// Filter out the metadata deny rule
347→				filteredRules := make([]string, 0, len(denyRules))
348→				for _, rule := range denyRules {
349→					if rule != metadataDenyRule {
350→						filteredRules = append(filteredRules, rule)
351→					}
352→				}
353→				if len(filteredRules) > 0 {
354→					denyJSON, err := json.Marshal(filteredRules)
355→					if err == nil {
356→						rawPermissions["deny"] = denyJSON
357→					}
358→				} else {
359→					// Remove empty deny array
360→					delete(rawPermissions, "deny")
361→				}
362→			}
363→		}
364→
365→		// If permissions is empty, remove it entirely
366→		if len(rawPermissions) > 0 {
367→			permJSON, err := json.Marshal(rawPermissions)
368→			if err == nil {
369→				rawSettings["permissions"] = permJSON
370→			}
371→		} else {
372→			delete(rawSettings, "permissions")
373→		}
374→	}
375→
376→	// Marshal hooks back (preserving unknown hook types)
377→	if len(rawHooks) > 0 {
378→		hooksJSON, err := json.Marshal(rawHooks)
379→		if err != nil {
380→			return fmt.Errorf("failed to marshal hooks: %w", err)
381→		}
382→		rawSettings["hooks"] = hooksJSON
383→	} else {
384→		delete(rawSettings, "hooks")
385→	}
386→
387→	// Write back
388→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
389→	if err != nil {
390→		return fmt.Errorf("failed to marshal settings: %w", err)
391→	}
392→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
393→		return fmt.Errorf("failed to write settings.json: %w", err)
394→	}
395→	return nil
396→}
