225→// --- Transcript flush sentinel ---
226→
227→// stopHookSentinel is the string that appears in Claude Code's hook_progress
228→// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
229→const stopHookSentinel = "hooks claude-code stop"
230→
231→// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
232→// Falls back silently after a timeout.
233→func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
234→	const (
235→		maxWait      = 3 * time.Second
236→		pollInterval = 50 * time.Millisecond
237→		tailBytes    = 4096
238→		maxSkew      = 2 * time.Second
239→	)
240→
241→	logCtx := logging.WithComponent(ctx, "agent.claudecode")
242→
243→	// Fast path: skip the poll loop when the sentinel can't possibly appear.
244→	// - File doesn't exist: nothing to poll.
245→	// - File is stale (unmodified for 2+ min): agent isn't running anymore.
246→	//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
247→	//   without firing stop hook).
248→	const staleThreshold = 2 * time.Minute
249→	info, err := os.Stat(transcriptPath)
250→	if err != nil {
251→		// Most likely the file doesn't exist; other errors (permission, etc.)
252→		// would also prevent polling, so skip the wait either way.
253→		return
254→	}
255→	fileAge := time.Since(info.ModTime())
256→	if fileAge > staleThreshold {
257→		logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
258→			slog.Duration("file_age", fileAge),
259→		)
260→		return
261→	}
262→
263→	deadline := time.Now().Add(maxWait)
264→	for time.Now().Before(deadline) {
265→		if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
266→			logging.Debug(logCtx, "transcript flush sentinel found",
267→				slog.Duration("wait", time.Since(hookStartTime)),
268→			)
269→			return
270→		}
271→		time.Sleep(pollInterval)
272→	}
273→	logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
274→		slog.Duration("timeout", maxWait),
275→	)
276→}
277→
278→// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
279→func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
280→	f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
281→	if err != nil {
282→		return false
283→	}
284→	defer f.Close()
285→
286→	info, err := f.Stat()
287→	if err != nil {
288→		return false
289→	}
290→	offset := info.Size() - tailBytes
291→	if offset < 0 {
292→		offset = 0
293→	}
294→	buf := make([]byte, info.Size()-offset)
295→	if _, err := f.ReadAt(buf, offset); err != nil {
296→		return false
297→	}
298→
299→	lines := strings.Split(string(buf), "\n")
300→	for _, line := range lines {
301→		line = strings.TrimSpace(line)
302→		if line == "" || !strings.Contains(line, stopHookSentinel) {
303→			continue
304→		}
305→
306→		var entry struct {
307→			Timestamp string `json:"timestamp"`
308→		}
309→		if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
310→			continue
311→		}
312→		ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
313→		if err != nil {
314→			ts, err = time.Parse(time.RFC3339, entry.Timestamp)
315→			if err != nil {
316→				continue
317→			}
318→		}
319→		// Validate timestamp is within acceptable range:
320→		// - Not too far in the past (before hook started minus skew)
321→		// - Not too far in the future (after hook started plus skew)
322→		lowerBound := hookStartTime.Add(-maxSkew)
323→		upperBound := hookStartTime.Add(maxSkew)
324→		if ts.After(lowerBound) && ts.Before(upperBound) {
325→			return true
326→		}
327→	}
328→	return false
329→}
