14→// fileEditsPath returns the path to the file edits JSONL file for a session.
15→func (s *StateStore) fileEditsPath(sessionID string) string {
16→	return filepath.Join(s.stateDir, sessionID+"-edits.jsonl")
17→}
18→
19→// AppendFileEdit appends a single FileEdit record to the session's edit log.
20→// This is an append-only operation -- no read-modify-write cycle.
21→func (s *StateStore) AppendFileEdit(sessionID string, edit agent.FileEdit) error {
22→	if err := validation.ValidateSessionID(sessionID); err != nil {
23→		return fmt.Errorf("invalid session ID: %w", err)
24→	}
25→
26→	if err := os.MkdirAll(s.stateDir, 0o750); err != nil {
27→		return fmt.Errorf("failed to create state directory: %w", err)
28→	}
29→
30→	path := s.fileEditsPath(sessionID)
31→	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600) //nolint:gosec // G304: path built from validated session ID
32→	if err != nil {
33→		return fmt.Errorf("failed to open file edits log: %w", err)
34→	}
35→	defer f.Close()
36→
37→	data, err := json.Marshal(edit)
38→	if err != nil {
39→		return fmt.Errorf("failed to marshal file edit: %w", err)
40→	}
41→	data = append(data, '\n')
42→
43→	if _, err := f.Write(data); err != nil {
44→		return fmt.Errorf("failed to write file edit: %w", err)
45→	}
46→	return nil
47→}
48→
49→// ReadFileEdits reads all FileEdit records from the session's edit log.
50→// Returns empty slice (not error) if the log doesn't exist.
51→func (s *StateStore) ReadFileEdits(sessionID string) ([]agent.FileEdit, error) {
52→	if err := validation.ValidateSessionID(sessionID); err != nil {
53→		return nil, fmt.Errorf("invalid session ID: %w", err)
54→	}
55→
56→	path := s.fileEditsPath(sessionID)
57→	f, err := os.Open(path) //nolint:gosec // G304: path built from validated session ID
58→	if os.IsNotExist(err) {
59→		return nil, nil
60→	}
61→	if err != nil {
62→		return nil, fmt.Errorf("failed to open file edits log: %w", err)
63→	}
64→	defer f.Close()
65→
66→	var edits []agent.FileEdit
67→	scanner := bufio.NewScanner(f)
68→	for scanner.Scan() {
69→		line := scanner.Bytes()
70→		if len(line) == 0 {
71→			continue
72→		}
73→		var edit agent.FileEdit
74→		if err := json.Unmarshal(line, &edit); err != nil {
75→			continue // Skip malformed lines
76→		}
77→		edits = append(edits, edit)
78→	}
79→	if err := scanner.Err(); err != nil {
80→		return edits, fmt.Errorf("failed to read file edits log: %w", err)
81→	}
82→	return edits, nil
83→}
84→
85→// ClearFileEdits removes the session's edit log file.
86→func (s *StateStore) ClearFileEdits(sessionID string) error {
87→	if err := validation.ValidateSessionID(sessionID); err != nil {
88→		return fmt.Errorf("invalid session ID: %w", err)
89→	}
90→
91→	path := s.fileEditsPath(sessionID)
92→	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
93→		return fmt.Errorf("failed to remove file edits log: %w", err)
94→	}
95→	return nil
96→}
