	)
	edits, err := stateStore.ReadFileEdits(sessionID)
	if err != nil {
		t.Fatalf("failed to read file edits: %v", err)
	}
	if len(edits) != 3 {
		t.Fatalf("edits count = %d, want 3", len(edits))
	}
}

// TestPostFileEdit_NoSession verifies that the post-file-edit hook does not
