	env := NewFeatureBranchEnv(t)
	sessionID := "test-session-edit-6"

	// Start a session turn
	if err := env.SimulateUserPromptSubmit(sessionID); err != nil {
		t.Fatalf("user-prompt-submit failed: %v", err)
	}

