// hook_registry.go provides hook command registration for agents.
// The lifecycle dispatcher (DispatchLifecycleEvent) handles all lifecycle events.
// PostTodo is the only hook that's handled directly (not via lifecycle dispatcher).
package cli

import (
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/strategy"

	"github.com/spf13/cobra"
)

// agentHookLogCleanup stores the cleanup function for agent hook logging.
// Set by PersistentPreRunE, called by PersistentPostRunE.
var agentHookLogCleanup func()

// currentHookAgentName stores the agent name for the currently executing hook.
// Set by newAgentHookVerbCmdWithLogging before calling the handler.
// This allows handlers to know which agent invoked the hook without guessing.
var currentHookAgentName types.AgentName

// GetCurrentHookAgent returns the agent for the currently executing hook.
// Returns the agent based on the hook command structure (e.g., "entire hooks claude-code ...")
// rather than guessing from directory presence.
// Falls back to GetAgent() if not in a hook context.
func GetCurrentHookAgent() (agent.Agent, error) {
	if currentHookAgentName == "" {
		return nil, errors.New("not in a hook context: agent name not set")
	}

	ag, err := agent.Get(currentHookAgentName)
	if err != nil {
		return nil, fmt.Errorf("getting hook agent %q: %w", currentHookAgentName, err)
	}
	return ag, nil
}

// newAgentHooksCmd creates a hooks subcommand for an agent that implements HookSupport.
// It dynamically creates subcommands for each hook the agent supports.
func newAgentHooksCmd(agentName types.AgentName, handler agent.HookSupport) *cobra.Command {
	cmd := &cobra.Command{
		Use:    string(agentName),
		Short:  handler.Description() + " hook handlers",
		Hidden: true,
		PersistentPreRunE: func(cmd *cobra.Command, _ []string) error {
			agentHookLogCleanup = initHookLogging(cmd.Context())
			return nil
		},
		PersistentPostRunE: func(_ *cobra.Command, _ []string) error {
			if agentHookLogCleanup != nil {
				agentHookLogCleanup()
			}
			return nil
		},
	}

	for _, hookName := range handler.HookNames() {
		cmd.AddCommand(newAgentHookVerbCmdWithLogging(agentName, hookName))
	}

	return cmd
}

// getHookType returns the hook type based on the hook name.
// Returns "subagent" for task-related hooks (pre-task, post-task, post-todo),
// "tool" for tool-related hooks (before-tool, after-tool),
// "agent" for all other agent hooks.
func getHookType(hookName string) string {
	switch hookName {
	case claudecode.HookNamePreTask, claudecode.HookNamePostTask, claudecode.HookNamePostTodo:
		return "subagent"
	case claudecode.HookNamePostFileEdit:
		return "tool"
	case geminicli.HookNameBeforeTool, geminicli.HookNameAfterTool:
		return "tool"
	default:
		return "agent"
	}
}

// newAgentHookVerbCmdWithLogging creates a command for a specific hook verb with structured logging.
// It uses the lifecycle dispatcher (ParseHookEvent → DispatchLifecycleEvent) as the primary path.
// PostTodo is handled directly as it's Claude-specific and not part of the lifecycle dispatcher.
func newAgentHookVerbCmdWithLogging(agentName types.AgentName, hookName string) *cobra.Command {
	return &cobra.Command{
		Use:    hookName,
		Hidden: true,
		Short:  "Called on " + hookName,
		RunE: func(cmd *cobra.Command, _ []string) error {
			// Skip silently if not in a git repository - hooks shouldn't prevent the agent from working
			if _, err := paths.WorktreeRoot(cmd.Context()); err != nil {
				return nil
			}

			// Skip if Entire is not enabled
			enabled, err := IsEnabled(cmd.Context())
			if err == nil && !enabled {
				return nil
			}

			start := time.Now()

			// Initialize logging context with agent name
			ctx := logging.WithAgent(logging.WithComponent(cmd.Context(), "hooks"), agentName)

			// Strategy name for logging
			strategyName := strategy.StrategyNameManualCommit

			hookType := getHookType(hookName)

			logging.Debug(ctx, "hook invoked",
				slog.String("hook", hookName),
				slog.String("hook_type", hookType),
				slog.String("strategy", strategyName),
			)

			// Set the current hook agent so handlers can retrieve it
			currentHookAgentName = agentName
			defer func() { currentHookAgentName = "" }()

			// Use the lifecycle dispatcher for all hooks
			var hookErr error
			ag, agentErr := agent.Get(agentName)
			if agentErr != nil {
				return fmt.Errorf("failed to get agent %q: %w", agentName, agentErr)
			}

			handler, ok := ag.(agent.HookSupport)
			if !ok {
				return fmt.Errorf("agent %q does not support hooks", agentName)
			}

			// Use cmd.InOrStdin() to support testing with cmd.SetIn()
			event, parseErr := handler.ParseHookEvent(ctx, hookName, cmd.InOrStdin())
			if parseErr != nil {
				return fmt.Errorf("failed to parse hook event: %w", parseErr)
			}

			switch {
			case event != nil:
				// Lifecycle event -- use the generic dispatcher
				hookErr = DispatchLifecycleEvent(ctx, ag, event)
			case agentName == agent.AgentNameClaudeCode && hookName == claudecode.HookNamePostTodo:
				// PostTodo is Claude-specific: creates incremental checkpoints during subagent execution
				hookErr = handleClaudeCodePostTodo(ctx)
			case agentName == agent.AgentNameClaudeCode && hookName == claudecode.HookNamePostFileEdit:
				// PostFileEdit updates FilesTouched in real-time for mid-turn commits
				hookErr = handleClaudeCodePostFileEdit(ctx)
			}
			// Other pass-through hooks (nil event, no special handling) are no-ops

			logging.LogDuration(ctx, slog.LevelDebug, "hook completed", start,
				slog.String("hook", hookName),
				slog.String("hook_type", hookType),
				slog.String("strategy", strategyName),
				slog.Bool("success", hookErr == nil),
			)

			return hookErr
		},
	}
}

package cli

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
)

// FileEditHookInput represents parsed input from PostToolUse[Write|Edit] hooks.
type FileEditHookInput struct {
	SessionID    string
	ToolName     string
	ToolUseID    string
	FilePath     string
	LinesAdded   int
	LinesRemoved int
}

// fileEditToolInputWrite is the tool_input structure for the Write tool.
type fileEditToolInputWrite struct {
	FilePath string `json:"file_path"`
	Content  string `json:"content"`
}

// fileEditToolInputEdit is the tool_input structure for the Edit tool.
type fileEditToolInputEdit struct {
	FilePath  string `json:"file_path"`
	OldString string `json:"old_string"`
	NewString string `json:"new_string"`
}

// parseFileEditHookInput parses PostToolUse[Write|Edit] hook input from reader.
// Extracts file path and computes line counts from the tool payload.
func parseFileEditHookInput(r io.Reader) (*FileEditHookInput, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("failed to read input: %w", err)
	}
	if len(data) == 0 {
		return nil, errors.New("empty input")
	}

	var raw SubagentCheckpointHookInput
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("failed to parse JSON: %w", err)
	}

	result := &FileEditHookInput{
		SessionID: raw.SessionID,
		ToolName:  raw.ToolName,
		ToolUseID: raw.ToolUseID,
	}

	switch raw.ToolName {
	case claudecode.ToolWrite:
		var input fileEditToolInputWrite
		if err := json.Unmarshal(raw.ToolInput, &input); err != nil {
			return nil, fmt.Errorf("failed to parse Write tool_input: %w", err)
		}
		result.FilePath = input.FilePath
		result.LinesAdded = agent.CountLines(input.Content)
		result.LinesRemoved = 0
	case claudecode.ToolEdit:
		var input fileEditToolInputEdit
		if err := json.Unmarshal(raw.ToolInput, &input); err != nil {
			return nil, fmt.Errorf("failed to parse Edit tool_input: %w", err)
		}
		result.FilePath = input.FilePath
		result.LinesAdded = agent.CountLines(input.NewString)
		result.LinesRemoved = agent.CountLines(input.OldString)
	default:
		return nil, fmt.Errorf("unsupported tool: %s", raw.ToolName)
	}

	return result, nil
}

// hooks_claudecode_postfileedit.go contains the PostFileEdit hook handler for Claude Code.
// This hook tracks file edits in real-time by appending to the session's edit log
// and merging edited file paths into FilesTouched in the session state.
package cli

import (
	"context"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"slices"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// handleClaudeCodePostFileEdit handles the PostToolUse[Write|Edit] hook.
// It tracks file edits in real-time for mid-turn commit attribution.
// All errors are non-fatal: logged as warnings and return nil.
func handleClaudeCodePostFileEdit(ctx context.Context) error {
	return handleClaudeCodePostFileEditFromReader(ctx, os.Stdin)
}

// handleClaudeCodePostFileEditFromReader is the testable version that accepts an io.Reader.
func handleClaudeCodePostFileEditFromReader(ctx context.Context, reader io.Reader) error {
	input, err := parseFileEditHookInput(reader)
	if err != nil {
		logging.Warn(ctx, "failed to parse post-file-edit input", slog.Any("error", err))
		return nil
	}

	logging.Debug(ctx, "post-file-edit",
		slog.String("hook", "post-file-edit"),
		slog.String("tool_name", input.ToolName),
		slog.String("file_path", input.FilePath),
		slog.String("session_id", input.SessionID),
	)

	// Verify session state exists before writing any files to avoid orphan edits
	state, err := strategy.LoadSessionState(ctx, input.SessionID)
	if err != nil {
		logging.Warn(ctx, "failed to load session state for file edit",
			slog.String("session_id", input.SessionID),
			slog.Any("error", err),
		)
		return nil
	}
	if state == nil {
		// No active session state - skip to avoid creating orphan edit logs
		return nil
	}

	// Normalize path relative to repo root
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Warn(ctx, "failed to get repo root for file edit", slog.Any("error", err))
		return nil
	}

	absPath := input.FilePath
	if !filepath.IsAbs(absPath) {
		absPath = filepath.Join(repoRoot, absPath)
	}
	relPath := filepath.ToSlash(paths.ToRelativePath(absPath, repoRoot))
	if relPath == "" {
		// Path is outside repo, skip silently
		return nil
	}

	// Determine action from tool name
	var action agent.FileEditAction
	switch input.ToolName {
	case claudecode.ToolWrite:
		action = agent.FileEditActionWrite
	case claudecode.ToolEdit:
		action = agent.FileEditActionEdit
	default:
		action = agent.FileEditAction(input.ToolName)
	}

	edit := agent.FileEdit{
		FilePath:     relPath,
		Action:       action,
		ToolName:     input.ToolName,
		LinesAdded:   input.LinesAdded,
		LinesRemoved: input.LinesRemoved,
		Timestamp:    time.Now(),
	}

	// Append to JSONL edit log
	store, err := session.NewStateStore(ctx)
	if err != nil {
		logging.Warn(ctx, "failed to create state store for file edit", slog.Any("error", err))
		return nil
	}
	if err := store.AppendFileEdit(input.SessionID, edit); err != nil {
		logging.Warn(ctx, "failed to append file edit", slog.Any("error", err))
		// Continue to try updating FilesTouched even if JSONL append fails
	}

	// Merge into FilesTouched in session state
	if !slices.Contains(state.FilesTouched, relPath) {
		state.FilesTouched = append(state.FilesTouched, relPath)
		if err := strategy.SaveSessionState(ctx, state); err != nil {
			logging.Warn(ctx, "failed to save session state after file edit", slog.Any("error", err))
		}
	}

	return nil
}

